// Builds the responsive WebP set in public/images from the untouched originals
// kept in assets/originals. Nothing is cropped, recoloured or retouched: every
// variant is a plain downscale of the original, and transparency is preserved.
//
//   bun run images:optimize
//
// The generated files are written as <name>-<width>.webp and described in
// src/image-manifest.ts, which the <Img> component reads for its srcset,
// intrinsic size and every image reference in the app.
import { existsSync, mkdirSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'

const root = fileURLToPath(new URL('..', import.meta.url))
const SRC = join(root, 'assets/originals')
const OUT = join(root, 'public/images')
const MANIFEST = join(root, 'src/image-manifest.ts')

// Product cut-outs keep their alpha channel. They are sized by the jar height
// the layout actually draws (hero 444–533px, product page ~500px), so the
// ladder tops out at 1600px tall — enough for a 2x screen — instead of the
// owner's 2560px master. Quality 86 with full alpha quality keeps the labels,
// fine print and Arabic script crisp without the ringing that low settings add.
const PRODUCTS = ['amlou-almond', 'amlou-cashew', 'amlou-chocolate', 'amlou-peanut', 'zammita', 'chebakia', 'argan-oil']
const PRODUCT_HEIGHTS = [280, 520, 900, 1300, 1600]
const PRODUCT_MAX_WIDTH = 1920
const PRODUCT_WEBP = { quality: 86, alphaQuality: 100, effort: 6, smartSubsample: true }

// Editorial photographs (already opaque). Fixed width ladders, since they are
// drawn as full-bleed or half-width blocks rather than fitted cut-outs.
const PHOTOS = [
  { name: 'farm-hill', widths: [640, 1024, 1600] },
  { name: 'harvest', widths: [480, 800, 1067] },
  { name: 'kitchen', widths: [640, 1024, 1600] },
  { name: 'r-bruschetta', widths: [480, 800, 1200, 1600] },
  { name: 'r-cake', widths: [480, 800, 1200, 1600] },
  { name: 'r-crostini', widths: [480, 800, 1200, 1600] },
  { name: 'r-pasta', widths: [480, 800, 1200, 1600] },
  { name: 'r-tart', widths: [480, 800, 1200, 1600] },
]
const PHOTO_WEBP = { quality: 78, effort: 6, smartSubsample: true }

const sourceOf = (name) => {
  for (const ext of ['.png', '.webp', '.jpg', '.jpeg']) {
    const p = join(SRC, name + ext)
    if (existsSync(p)) return p
  }
  throw new Error(`missing original for ${name} in assets/originals`)
}

const kb = (n) => `${(n / 1024).toFixed(0)} KB`
const rows = []
const manifest = {}

mkdirSync(OUT, { recursive: true })

async function emit(name, source, widths, settings, { hasAlpha }) {
  const meta = await sharp(source).metadata()
  const scale = meta.height / meta.width
  const kept = []
  for (const w of widths) {
    if (w > meta.width) continue // never upscale
    const h = Math.round(w * scale)
    const file = join(OUT, `${name}-${w}.webp`)
    const info = await sharp(source)
      .resize({ width: w, kernel: 'lanczos3' })
      .webp({ ...settings, preset: 'photo' })
      .toFile(file)
    kept.push({ w, h, bytes: statSync(file).size })
    if (!kept.length) throw new Error(`no variant written for ${name}`)
    const out = await sharp(file).metadata()
    if (out.width !== w || out.height !== h) throw new Error(`${name}-${w}: got ${out.width}x${out.height}, want ${w}x${h}`)
    if (hasAlpha && !out.hasAlpha) throw new Error(`${name}-${w}: alpha channel lost`)
    rows.push({ name, variant: `${name}-${w}.webp`, size: `${out.width}x${out.height}`, bytes: info.size, alpha: out.hasAlpha })
  }
  const largest = kept[kept.length - 1]
  manifest[name] = { w: largest.w, h: largest.h, widths: kept.map((k) => k.w) }
}

for (const name of PRODUCTS) {
  const source = sourceOf(name)
  const meta = await sharp(source).metadata()
  // Height-driven ladder: the fitted jar is drawn by height, so a fixed height
  // keeps every product equally sharp. Widest variant is capped for the wide
  // amlou frames, whose full width is mostly transparent margin.
  const widths = [...new Set(PRODUCT_HEIGHTS.map((h) => Math.min(PRODUCT_MAX_WIDTH, Math.round(h * (meta.width / meta.height)))))]
    .filter((w) => w <= meta.width)
    .sort((a, b) => a - b)
  await emit(name, source, widths, PRODUCT_WEBP, { hasAlpha: meta.hasAlpha === true })
}

for (const { name, widths } of PHOTOS) {
  const source = sourceOf(name)
  const meta = await sharp(source).metadata()
  await emit(name, source, widths, PHOTO_WEBP, { hasAlpha: meta.hasAlpha === true })
}

// Files in public/images that no longer belong to a generated set.
const generated = new Set(Object.keys(manifest).flatMap((n) => manifest[n].widths.map((w) => `${n}-${w}.webp`)))
const stale = readdirSync(OUT).filter((f) => !generated.has(f) && !/^(box|jar)-/.test(f))

const body = `// GENERATED by scripts/optimize-images.mjs — do not edit by hand.
// Intrinsic size and the width ladder of every optimised image in
// public/images, used for srcset, width/height attributes and the fallback src.
export const imageManifest: Record<string, { w: number; h: number; widths: number[] }> = ${JSON.stringify(manifest, null, 2)}
`
writeFileSync(MANIFEST, body)

const pad = (s, n) => String(s).padEnd(n)
console.log(pad('file', 26) + pad('pixels', 12) + pad('size', 10) + 'alpha')
for (const r of rows) console.log(pad(r.variant, 26) + pad(r.size, 12) + pad(kb(r.bytes), 10) + (r.alpha ? 'yes' : '-'))
const total = rows.reduce((s, r) => s + r.bytes, 0)
console.log(`\n${rows.length} variants, ${kb(total)} total in public/images`)
if (stale.length) console.log(`not part of the generated set (left untouched): ${stale.join(', ')}`)
